[InitializeOnLoadMethod]static void BuildMissingScene(){if(System.IO.File.Exists(ScenePath))return;if(EditorApplication.isPlayingOrWillChangePlaymode){EditorApplication.playModeStateChanged-=OnPlayModeChanged;EditorApplication.playModeStateChanged+=OnPlayModeChanged;return;}EditorApplication.delayCall+=BuildIfEditorReady;}
