[MenuItem("Mojinloop/Rebuild Desktop RPG Prototype")]public static void Build(){EnsureFolders();var window=Asset<DesktopWindowSettings>("Assets/Data/DesktopWindowSettings.asset");var gameplay=Asset<GameplaySettings>("Assets/Data/GameplaySettings.asset");var heroStats=Asset<HeroStats>("Assets/Data/HeroStats.asset");var monsterData=Asset<MonsterData>("Assets/Data/MonsterData.asset");var placeholder=MakeSprite();var heroSprite=ReferenceSprite("Assets/Reference/character.png");var monsterSprite=ReferenceSprite("Assets/Reference/monster.png");CreatePrefab<HeroController>("Hero",heroSprite,Color.white,"Assets/Prefabs/Hero.prefab",new Vector3(1.15f,1.15f,1));CreatePrefab<MonsterController>("Monster",monsterSprite,Color.white,"Assets/Prefabs/Monster.prefab",new Vector3(1.15f,1.15f,1));CreateTextPrefab<DamagePopup>("Damage Popup","Assets/Prefabs/DamagePopup.prefab",24);CreateTextPrefab<CoinDropEffect>("Coin Effect","Assets/Prefabs/CoinEffect.prefab",18);var heroPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Hero.prefab").GetComponent<HeroController>();var monsterPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Monster.prefab").GetComponent<MonsterController>();var damagePrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/DamagePopup.prefab").GetComponent<DamagePopup>();var coinPrefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/CoinEffect.prefab").GetComponent<CoinDropEffect>();CreateBackgroundPrefab(placeholder);
var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("DesktopRpgPrototype");var systems=Child(root,"Systems");var world=Child(root,"World");var effects=Child(root,"Effects");effects.name="Effects";var uiRoot=Child(root,"UI");
var cameraGo=new GameObject("Main Camera",typeof(Camera));cameraGo.tag="MainCamera";var cam=cameraGo.GetComponent<Camera>();cam.orthographic=true;cam.orthographicSize=2.4f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(0,0,0,0);cameraGo.transform.position=new Vector3(0,0,-10);
var canvasGo=new GameObject("Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvasGo.transform.SetParent(uiRoot.transform);var canvas=canvasGo.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=canvasGo.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(640,240);
var groundA=SpriteObject("Ground A",placeholder,new Color(.18f,.3f,.22f,1),world.transform,new Vector3(0,-1.85f,0),new Vector3(13,.9f,1));var groundB=SpriteObject("Ground B",placeholder,new Color(.16f,.27f,.2f,1),world.transform,new Vector3(13,-1.85f,0),new Vector3(13,.9f,1));var hero=Object.Instantiate(heroPrefab,world.transform);hero.name="Hero";hero.transform.position=new Vector3(-3.8f,-1.05f,0);var spawn=Child(world,"MonsterSpawnPoint").transform;spawn.position=new Vector3(5,-1.08f,0);var combatPoint=Child(world,"CombatPoint");combatPoint.transform.position=new Vector3(-2.45f,-1.08f,0);
var input=systems.AddComponent<GlobalInputActivityController>();var activity=systems.AddComponent<InputActivityState>();var desktop=systems.AddComponent<DesktopWindowController>();var scroller=systems.AddComponent<BackgroundScroller>();var spawner=systems.AddComponent<MonsterSpawner>();var combat=systems.AddComponent<CombatController>();var flow=systems.AddComponent<GameFlowController>();var anim=hero.gameObject.AddComponent<HeroAnimationController>();var dmgRoot=Child(effects,"DamagePopupRoot");var coinRoot=Child(effects,"CoinEffectRoot");
var hp=Label(canvasGo.transform,"HP 100 / 100",new Vector2(10,-10),TextAnchor.UpperLeft,18);hp.name="HeroStatus";var coins=Label(canvasGo.transform,"COIN 0",new Vector2(-10,-10),TextAnchor.UpperRight,18);coins.name="CoinText";var inputLabel=Label(canvasGo.transform,"IDLE",new Vector2(10,10),TextAnchor.LowerLeft,14);inputLabel.name="DebugStatus";var pause=Label(canvasGo.transform,"",new Vector2(0,0),TextAnchor.MiddleCenter,24);
